function omoInterfaceUiT(string $key, array $variables = []): string
{
    static $bundles = [];
    $sourceLang = omoInterfaceUiSourceLang();
    $locale = omoGetTranslationLocale();
    $bundle = $bundles[$locale] ??= loadTranslationBundle('omo_interface_ui', $locale, $sourceLang);
    return t($key, $variables, $bundle, $sourceLang);
}
